import{_ as a,o as e,c as r,a5 as d}from"./chunks/framework.bIR-4glx.js";const p=JSON.parse('{"title":"工具箱总览：先选问题，再选工具","description":"按起点、能力训练、AI 协作、作品交付、复盘与恢复分流全部模板，帮助读者用最少记录建立一次完整行动闭环。","frontmatter":{"title":"工具箱总览：先选问题，再选工具","socialImage":"/assets/social/templates-zh.png","socialImageAlt":"从基线、练习、复测到下一步的实践模板","description":"按起点、能力训练、AI 协作、作品交付、复盘与恢复分流全部模板，帮助读者用最少记录建立一次完整行动闭环。","updated":"2026-10-04T00:00:00.000Z"},"headers":[],"relativePath":"templates/toolkit.md","filePath":"templates/toolkit.md","lastUpdated":1791072000000}'),i={name:"templates/toolkit.md"};function h(n,t,s,l,o,c){return e(),r("div",null,[...t[0]||(t[0]=[d(`<h1 id="工具箱总览-先选问题-再选工具" tabindex="-1">工具箱总览：先选问题，再选工具 <a class="header-anchor" href="#工具箱总览-先选问题-再选工具" aria-label="Permalink to &quot;工具箱总览：先选问题，再选工具&quot;">​</a></h1><p>模板不是另一套需要收集的课程。它们是几张可以反复使用的工作纸：把眼前的问题写清楚，留下一个未经修饰的样本，做一次行动，再让反馈决定下一步。</p><p>如果你不知道从哪里开始，只选一张。写得不完整也可以；一张真实使用过的工作纸，比十张空白模板更有价值。</p><h2 id="先回答-我现在卡在哪里" tabindex="-1">先回答：我现在卡在哪里？ <a class="header-anchor" href="#先回答-我现在卡在哪里" aria-label="Permalink to &quot;先回答：我现在卡在哪里？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>当前卡点</th><th>第一个工具</th><th>接着打开</th><th>这张工具不能替你证明什么</th></tr></thead><tbody><tr><td>工具很多，不知道实际怎样填写</td><td><a href="./toolkit-walkthrough">工具箱实战</a></td><td><a href="./learning-state">学习状态</a></td><td>合成示例不能证明同样的计划适合你</td></tr><tr><td>不知道目标或基线</td><td><a href="./learning-state">学习状态</a></td><td><a href="./english-diagnostic">英语能力诊断</a></td><td>不能替你决定一个永远正确的方向</td></tr><tr><td>准备海外岗位、英文面试或远程协作</td><td><a href="./interview-evidence">求职英语证据卡</a></td><td><a href="./../threads/part-1/8-job-search-english">求职英语篇</a></td><td>不能保证 offer，也不能把一个等级变成统一录用线</td></tr><tr><td>想开始一个 90 天周期</td><td><a href="./90-day-cycle">九十日行动总表</a></td><td><a href="./rhythm-ledger">节律账本</a></td><td>不能保证计划一定成功或持续</td></tr><tr><td>每周节奏反复中断</td><td><a href="./rhythm-ledger">节律账本</a></td><td><a href="./weekly-review">每周复盘</a></td><td>不能把疲惫、疾病或责任解释成懒惰</td></tr><tr><td>有样本却说不清是否真的改变</td><td><a href="./evidence-chain">证据链</a></td><td><a href="./../threads/part-3/5-evidence-and-transfer">证据篇</a></td><td>不能把一次顺利表现推成稳定能力</td></tr><tr><td>读完有感触，却不知道七天后是否留下什么</td><td><a href="./reader-field-note">读者实践回执</a></td><td><a href="./evidence-chain">证据链</a></td><td>不能把一次个人体验推成普遍效果</td></tr><tr><td>正在帮助初中阶段的孩子学习</td><td><a href="./family-learning-agreement">家庭学习共同协议</a></td><td><a href="./../threads/part-4/family-learning">家庭学习篇</a></td><td>不能替孩子选择人生、替代学校或诊断困难</td></tr><tr><td>单词认识却不会使用</td><td><a href="./vocabulary-audit">词汇证据卡</a></td><td><a href="./../threads/part-1/2-vocabulary">词汇篇</a></td><td>不能用卡片数量替代语境中的表现</td></tr><tr><td>规则似乎懂了，真实表达仍反复出错</td><td><a href="./grammar-evidence">语法证据卡</a></td><td><a href="./../threads/part-1/grammar">语法篇</a></td><td>不能把一次改对、风格偏好或 AI 润色当成稳定语法能力</td></tr><tr><td>收藏了很多音频，仍靠字幕或不知道每一遍做什么</td><td><a href="./listening-audit">听力证据卡</a></td><td><a href="./../threads/part-1/3-listening">听力篇</a></td><td>不能把播放时长、重复次数、字幕理解或跟读顺畅当成稳定听力</td></tr><tr><td>技术文档读得慢、逐词翻译或读完无法交付</td><td><a href="./reading-evidence">阅读证据卡</a></td><td><a href="./../threads/part-1/4-reading">阅读篇</a></td><td>不能把页数、划线数量、翻译或工具摘要当成独立理解与验证</td></tr><tr><td>只在背稿时流畅、害怕口音或遇到追问就卡住</td><td><a href="./speaking-evidence">口语证据卡</a></td><td><a href="./../threads/part-1/5-speaking">口语篇</a></td><td>不能把口音相似度、语音识别分数或一次重录当成稳定互动能力</td></tr><tr><td>写不出自己的初稿、依赖整句翻译或只剩工具成品</td><td><a href="./writing-evidence">写作证据卡</a></td><td><a href="./../threads/part-1/6-writing">写作篇</a></td><td>不能把流畅终稿、自动评分或一次修订当成署名能力与迁移</td></tr><tr><td>不知道怎样让 AI 参与</td><td><a href="./ai-task-brief">AI 任务简报</a></td><td><a href="./ai-learning-log">AI 学习记录</a></td><td>不能把模型回答自动变成事实或最终判断</td></tr><tr><td>新工具太多，不知道该学什么</td><td><a href="./ai-trend-radar">AI 趋势实验卡</a></td><td><a href="./../threads/part-3/6-ai-trends-and-learning-roadmap">AI 趋势与学习路线</a></td><td>不能把发布演示或未来假设当成自己的任务收益</td></tr><tr><td>有想法却没有可交付作品</td><td><a href="./artifact-brief">作品简报与交付卡</a></td><td><a href="./ai-project-scorecard">AI 项目评分卡</a></td><td>不能替你找到用户、承担责任或证明商业结果</td></tr><tr><td>想分析一个人物或项目故事</td><td><a href="./ai-case-review">AI 经历案例复盘</a></td><td><a href="./../threads/part-2/narrative-and-evidence">叙事与证据篇</a></td><td>不能把公开叙事当成独立审计</td></tr><tr><td>正在处理选择、注意力、关系或恢复</td><td><a href="./life-practice-toolkit">生活进阶工作表</a></td><td><a href="./../threads/part-2/decision">选择篇</a> · <a href="./../threads/part-3/3-attention-and-judgment">注意力篇</a> · <a href="./../threads/part-2/relationships">关系篇</a> · <a href="./../threads/part-2/recovery">恢复篇</a></td><td>不能替代医疗、心理、法律或财务专业支持</td></tr><tr><td>想关心身边人、接受支持或重新分担生活负担</td><td><a href="./life-practice-toolkit">关心与分担卡</a></td><td><a href="./../threads/part-2/care-and-carry-on">珍惜篇</a></td><td>不能给爱打分，也不能要求别人承担超出意愿和容量的支持</td></tr><tr><td>需要验证创业想法而非继续加功能</td><td><a href="./startup-experiment">创业实验卡</a></td><td><a href="./../threads/practice/customer-discovery">客户验证实操</a></td><td>不能把赞美、免费试用或一次付款当成可持续需求</td></tr><tr><td>想排查启动困难或做一次中断重启</td><td><a href="./consistency-plan">持续行动计划</a></td><td><a href="./../threads/practice/discipline-and-consistency">自律与坚持实操</a></td><td>不能把一次中断解释成意志或人格失败</td></tr><tr><td>要判断 AI 新版本能否交付</td><td><a href="./ai-evaluation">AI 评测记录</a></td><td><a href="./../threads/practice/ai-evaluation">AI 评测与可靠性</a></td><td>不能用小样本或人工修订后的正确率保证线上可靠性</td></tr></tbody></table><h2 id="把工具串成一次闭环" tabindex="-1">把工具串成一次闭环 <a class="header-anchor" href="#把工具串成一次闭环" aria-label="Permalink to &quot;把工具串成一次闭环&quot;">​</a></h2><p>第一次使用工具箱时，可以先完整走一遍<a href="./toolkit-walkthrough">跨会话 AI 学习合成案例</a>。不要同时填写全部模板。按下面的顺序，每一步只留下最必要的一份证据：</p><ol><li><strong>定位</strong>：用<a href="./learning-state">学习状态</a>或<a href="./english-diagnostic">英语能力诊断</a>写清真实场景、当前基线和完成标准；</li><li><strong>选择</strong>：如果周期较长，用<a href="./90-day-cycle">九十日行动总表</a>；如果只安排本周，用<a href="./rhythm-ledger">节律账本</a>；</li><li><strong>练习</strong>：按任务选择词汇、语法、听力、阅读、口语或写作证据卡；若目标是岗位面试，用<a href="./interview-evidence">求职英语证据卡</a>把陌生追问和异步写作一起纳入，先完成自己的第一版；</li><li><strong>协作</strong>：需要 AI 时，先填<a href="./ai-task-brief">AI 任务简报</a>，再把协作过程和关闭 AI 后的表现写进<a href="./ai-learning-log">AI 学习记录</a>；</li><li><strong>交付</strong>：有真实受众时使用<a href="./artifact-brief">作品简报与交付卡</a>，发布或试点后用<a href="./ai-project-scorecard">AI 项目评分卡</a>记录质量、成本、风险和回滚；</li><li><strong>复查</strong>：用<a href="./evidence-chain">证据链</a>把首版、即时表现、延迟保持与迁移放在一起，再用<a href="./weekly-review">每周复盘</a>决定只改变哪一个条件；</li><li><strong>回执</strong>：如果这次行动来自书中一章，用<a href="./reader-field-note">读者实践回执</a>记录哪一处真正进入行动、哪一处仍然不会用。</li></ol><p>这是一条可往返的路径。任何一步发现风险、容量下降或证据不足，都可以退回上一步缩小任务；退回不是浪费，而是让下一次行动更可信。</p><h2 id="三条使用规则" tabindex="-1">三条使用规则 <a class="header-anchor" href="#三条使用规则" aria-label="Permalink to &quot;三条使用规则&quot;">​</a></h2><h3 id="只追踪会改变决定的内容" tabindex="-1">只追踪会改变决定的内容 <a class="header-anchor" href="#只追踪会改变决定的内容" aria-label="Permalink to &quot;只追踪会改变决定的内容&quot;">​</a></h3><p>如果一个数字不能帮助你决定继续、降档、改变变量或停止，就不必长期记录。记录的目的不是让页面变满，而是让下一步变清楚。</p><h3 id="第一版必须尽量由人完成" tabindex="-1">第一版必须尽量由人完成 <a class="header-anchor" href="#第一版必须尽量由人完成" aria-label="Permalink to &quot;第一版必须尽量由人完成&quot;">​</a></h3><p>模板中的基线、首版和独立复测，应尽量在 AI 介入前或关闭 AI 后完成。工具可以帮助解释、比较和指出问题，但不能替你制造“我已经会了”的感觉。</p><h3 id="记录必须守住边界" tabindex="-1">记录必须守住边界 <a class="header-anchor" href="#记录必须守住边界" aria-label="Permalink to &quot;记录必须守住边界&quot;">​</a></h3><p>不要把密码、证件、精确住址、客户资料、医疗隐私或未授权的第三方内容粘贴进模板或模型。涉及健康、安全、法律、财务和持续失控时，先联系合格的专业人士或可信的支持者。</p><h2 id="一个最小开始" tabindex="-1">一个最小开始 <a class="header-anchor" href="#一个最小开始" aria-label="Permalink to &quot;一个最小开始&quot;">​</a></h2><p>今天只做四行：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我现在要解决的真实问题：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我已经拥有的基线证据：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">我在 25–45 分钟内要完成的最小输出：</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">完成后我会把证据保存在：</span></span></code></pre></div><p>完成后，选择最贴近任务的一张工具，给它一个日期和下一次复查时间。不要等所有栏目都填满才开始；开始之后，缺口才会变得具体。</p><p>相关入口：<a href="./toolkit-walkthrough">工具箱实战</a> ｜ <a href="./../threads/part-0/reader-guide">阅读指南：把书放回生活</a> ｜ <a href="./../reference/glossary">术语与方法索引</a> ｜ <a href="./../threads/part-4/rhythm-and-compounding">节律篇：让小事穿过时间</a></p>`,21)])])}const g=a(i,[["render",h]]);export{p as __pageData,g as default};
